<script>
(function(){var district=document.getElementById('nr-district'),village=document.getElementById('nr-village');function sync(clear){if(clear)village.value='0';Array.from(village.options).forEach(function(option){var invalid=option.value!=='0'&&district.value!=='0'&&option.dataset.district!==district.value;option.hidden=invalid;option.disabled=invalid;});}district.addEventListener('change',function(){sync(true);});sync(false);}());
</script>
